style.css:
@-moz-document domain("pinterest.com") {
/* Background and main layout */
    body, html {
        background-color: #ffe6f0 !important; /* Light pink background */
        color: #4a4a4a !important;            /* Dark text for contrast */
    }

    /* Header and navigation bar */
    header, nav, .AppHeader {
        background-color: #ffccd9 !important; /* Slightly darker pink */
        border-bottom: 1px solid #f8a6b5 !important;
    }

    /* Pin boards and feed cards */
    div[data-test-id="pin"] {
        background-color: #fff0f5 !important;
        border: 1px solid #ffb6c1 !important;
        border-radius: 10px !important;
    }

    /* Text (titles, buttons, etc.) */
    h1, h2, h3, h4, a, span, p {
        color: #4a2c2a !important;
    }

    /* Buttons */
    button {
        background-color: #ffb6c1 !important;
        color: white !important;
        border-radius: 6px !important;
        border: none !important;
    }

    button:hover {
        background-color: #ff99aa !important;
    }

    /* Search bar */
    input[type="search"], input[type="text"] {
        background-color: #fff0f5 !important;
        color: #4a2c2a !important;
        border: 1px solid #ffb6c1 !important;
    }

    /* Scrollbar (optional) */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-track {
        background: #ffe6f0;
    }

    ::-webkit-scrollbar-thumb {
        background: #ffb6c1;
    }

    ::-webkit-scrollbar-thumb:hover {
        background: #ff99aa;
    }
}
